cat >> tests/vitest/window-manager-close-focus.test.ts <<'EOF'

describe( 'WindowManager — keep on top', () => {
	let desktop: HTMLElement;
	let manager: WindowManager;

	const paintOrder = (): string[] =>
		manager
			.getAll()
			.slice()
			.sort(
				( x, y ) =>
					Number( x.element.style.zIndex ) - Number( y.element.style.zIndex ),
			)
			.map( ( w ) => w.id );

	beforeEach( () => {
		installHooksStub();
		_resetWindowControlRegistryForTests();
		registerBuiltInControls();
		desktop = makeDesktop();
		document.body.appendChild( desktop );
		manager = new WindowManager( desktop );
	} );

	afterEach( () => {
		for ( const w of manager.getAll() ) {
			w.destroy();
		}
		desktop.remove();
		_resetWindowControlRegistryForTests();
		clearHooksStub();
	} );

	test( 'a kept-on-top window stays above windows focused or opened after it', async () => {
		const a = await manager.open( cfg( 'a' ) );
		const b = await manager.open( cfg( 'b' ) );
		expect( manager.setAlwaysOnTop( 'a', true ) ).toBe( true );
		expect( a.alwaysOnTop ).toBe( true );

		manager.focus( b );
		const c = await manager.open( cfg( 'c' ) );

		expect( c.isFocused() ).toBe( true );
		expect( paintOrder() ).toEqual( [ 'b', 'c', 'a' ] );

		manager.setAlwaysOnTop( 'a', false );
		expect( paintOrder() ).toEqual( [ 'a', 'b', 'c' ] );
	} );

	test( 'several kept-on-top windows stack among themselves in focus order', async () => {
		const a = await manager.open( cfg( 'a' ) );
		await manager.open( cfg( 'b' ) );
		const c = await manager.open( cfg( 'c' ) );
		manager.setAlwaysOnTop( 'a', true );
		manager.setAlwaysOnTop( 'c', true );

		expect( paintOrder() ).toEqual( [ 'b', 'a', 'c' ] );
		manager.focus( a );
		expect( paintOrder() ).toEqual( [ 'b', 'c', 'a' ] );
		void c;
	} );

	test( 'a child of a kept-on-top owner stays above its owner', async () => {
		await manager.open( cfg( 'owner' ) );
		manager.setAlwaysOnTop( 'owner', true );
		await manager.openChild( 'owner', cfg( 'child' ) );
		await manager.open( cfg( 'other' ) );

		expect( paintOrder() ).toEqual( [ 'other', 'owner', 'child' ] );
	} );

	test( 'the title-bar pin toggles the state and reflects it', async () => {
		const a = await manager.open( cfg( 'a' ) );
		await manager.open( cfg( 'b' ) );
		const changed = vi.fn();
		document.addEventListener( 'os-window-changed', changed );
		const pin = a.element.querySelector< HTMLElement >(
			'.os-window__btn--always-on-top',
		);
		expect( pin ).not.toBeNull();

		pin!.dispatchEvent( new CustomEvent( 'os-button-activate' ) );

		expect( a.alwaysOnTop ).toBe( true );
		expect( pin!.getAttribute( 'aria-pressed' ) ).toBe( 'true' );
		expect( a.element.classList.contains( 'os-window--always-on-top' ) ).toBe( true );
		expect( paintOrder() ).toEqual( [ 'b', 'a' ] );
		expect( changed ).toHaveBeenCalledWith(
			expect.objectContaining( {
				detail: expect.objectContaining( { windowId: 'a', reason: 'always-on-top' } ),
			} ),
		);
		document.removeEventListener( 'os-window-changed', changed );

		pin!.dispatchEvent( new CustomEvent( 'os-button-activate' ) );
		expect( a.alwaysOnTop ).toBe( false );
		expect( pin!.getAttribute( 'aria-pressed' ) ).toBe( 'false' );
	} );
} );
EOF
